#!/usr/bin/env python3
"""Compile and run the production popular transition with Linux collaborator stubs."""
from pathlib import Path
import re,sys,subprocess,tempfile,os
source=Path(sys.argv[1] if len(sys.argv)>1 else Path(__file__).resolve().parents[2]/'Sources/gor/Media/MagnetBrowser.swift')
s=source.read_text()
method=re.search(r'    private func popular\(\) \{.*?\n    \}\n',s,re.S).group()
decl=re.search(r'    private var throttledUntil = .*',s).group()
template='import Foundation\nstruct MagnetUIndexFailure: Error { var reason: String { "failure" } }\nfinal class Task { func cancel() {}; func invalidateAndCancel() {} }\nfinal class Panel {\n var isHidden=true; var status=""; var key=""; var descending=false; var query=""; var invalidations=0\n func invalidateSelection(){invalidations += 1};func setStatus(_ s:String){status=s};func setQuery(_ s:String){query=s};func applySort(_ k:String,descending d:Bool){key=k;descending=d}\n}\nfinal class Provider { var calls=0;func popular(completion:@escaping(Result<[[String:Any]],MagnetUIndexFailure>)->Void){calls += 1} }\nfinal class UI { func wakeUI(){} }; final class AppDelegate { var controller:UI?=UI() };struct Application { var delegate:Any?=AppDelegate() };let NSApp=Application()\nfinal class Harness {\n private var generation=0;private var parseSerial=0;private var refreshRevision=0;private var reparsePending=false\n private var tasks:[Task]=[];private var sessions:[Task]=[];private var query="old";private var parsedProviders:[String:[[String:Any]]]=[:];private var failures:[String:String]=[:];private var pendingProviders:Set<String>=[]\n private var lastResponse:Int?=1;private let trackerQueue=OperationQueue();private var verdicts:[String:Int]=[:];private var scrapedHashes:Set<String>=[]\n private let panel=Panel();private let uindexProvider=Provider();private func parse(){}\n__DECL__\n__METHOD__\n func run(){\n  popular();precondition(generation==1 && uindexProvider.calls==1 && pendingProviders==["uindex"])\n  precondition(panel.key=="seeds" && panel.descending && panel.query=="" && !panel.isHidden)\n  precondition(panel.invalidations==1 && lastResponse==nil && query=="")\n  popular();precondition(generation==1 && uindexProvider.calls==1 && panel.status=="wait before searching again")\n  throttledUntil=Date.distantPast;popular();precondition(generation==2 && uindexProvider.calls==2)\n }\n}\nlet harness=Harness();harness.run();print("PASS actual popular method name resolution, initial admission, repeated-call throttle, state reset, resumed admission")\n'
with tempfile.TemporaryDirectory() as d:
 p=Path(d)/'state.swift';p.write_text(template.replace('__DECL__',decl).replace('__METHOD__',method))
 exe=Path(d)/'state';subprocess.run([os.environ.get('SWIFTC','swiftc'),str(p),'-o',str(exe)],check=True);subprocess.run([str(exe)],check=True)
